// Valider les parametres requis
const input = $input.first().json;
const body = input.body || input;

const projectId = body.project_id || null;
const stripeKey = body.stripe_key || null;
const webhookSecret = body.webhook_secret || null;
const displayName = body.display_name || projectId;
const tenantId = body.tenant_id || null;

// Backend credentials (auto-injected by chatbot-core 0.8.68+)
const backendApiUrl = body.backend_api_url || null;
const backendServiceToken = body.backend_service_token || null;

const errors = [];
if (!projectId) errors.push('project_id');
if (!stripeKey) errors.push('stripe_key');
if (!webhookSecret) errors.push('webhook_secret');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Valider le format des cles
if (!stripeKey.startsWith('sk_')) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'stripe_key doit commencer par sk_',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

if (!webhookSecret.startsWith('whsec_')) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'webhook_secret doit commencer par whsec_',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: projectId,
    stripe_key: stripeKey,
    webhook_secret: webhookSecret,
    display_name: displayName,
    backend_api_url: backendApiUrl,
    tenant_id: tenantId,
    backend_service_token: backendServiceToken,
    redis_key: `project:${projectId}`
  }
}];

// ── Parade #442/#467 — lire le STATUT RÉEL, jamais `|| 200` ──────────────────
//
// Le nœud HTTP porte désormais `fullResponse: true` + `neverError: true` : il émet
// { statusCode, body, headers } et ne lève plus sur un statut d'erreur. Reste le
// transport (délai, DNS, service éteint), où `onError: continueRegularOutput` fait
// émettre un objet d'erreur SANS statusCode — le statut réel n'existe alors que
// dans le message, sous la forme « 404 - {...} ».
function statutReel442(entree) {
  if (typeof entree.statusCode === 'number') return entree.statusCode;
  const brut = String((entree.error && entree.error.message) || entree.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  if (m) return parseInt(m[1], 10);
  return (entree.error || entree.code) ? 502 : 200;
}
// Le corps JSON de l'API, quand n8n l'a enfermé dans la chaîne du message d'erreur
// (doublement échappé). Sans ça le message reste `404 - "{\"detail\":…"`.
function corpsDansMessage442(entree) {
  const brut = String((entree.error && entree.error.message) || entree.message || '');
  const i = brut.indexOf('{'), j = brut.lastIndexOf('}');
  if (i < 0 || j <= i) return null;
  const bloc = brut.slice(i, j + 1);
  for (const essai of [bloc, bloc.replace(/\\"/g, '"').replace(/\\\\/g, '\\')]) {
    try { const o = JSON.parse(essai); if (o && typeof o === 'object') return o; } catch (e) { /* suivant */ }
  }
  return null;
}
// `detail` de FastAPI : parfois une chaîne, parfois une liste d'objets de validation.
function messageApi442(corps, defaut) {
  if (!corps) return defaut;
  const d = corps.detail;
  if (typeof d === 'string' && d) return d;
  if (Array.isArray(d) && d.length) {
    return d.map((e) => (e && e.msg) || JSON.stringify(e)).join(' ; ').slice(0, 300);
  }
  if (typeof corps.message === 'string' && corps.message) return corps.message;
  if (typeof corps.error === 'string' && corps.error) return corps.error;
  if (corps.error && typeof corps.error.message === 'string') return corps.error.message;
  return defaut;
}

const apiResult = $input.first().json;
const inputData = $('Validate Input').first().json;

const statut = statutReel442(apiResult);

// ⚠️ DÉFAUT CORRIGÉ LE 2026-11-06 — `Call API Admin` n'avait PAS `fullResponse`.
// Le nœud émettait donc le CORPS directement, et :
//   • `apiResult.statusCode` valait toujours undefined → le test
//     `if (apiResult.statusCode && apiResult.statusCode !== 200)` ne pouvait
//     JAMAIS être vrai. Un garde-fou inatteignable, comme #543.
//   • `apiResult.body` valait undefined → `responseBody` tombait à `{}` → la
//     réponse renvoyait `project_id` et `display_name` DE LA REQUÊTE, et
//     `environment: undefined`. Nous RECOPIONS la demande en la présentant comme
//     la réponse de l'API. Sur un workflow à 105 exécutions relevées.
// Les deux défauts étaient invisibles : la réponse avait exactement la forme
// attendue, et ses valeurs étaient celles que l'appelant venait d'envoyer.
const corpsApi = (apiResult.body !== undefined && apiResult.body !== null)
  ? apiResult.body
  : (corpsDansMessage442(apiResult) || {});

if (statut >= 400 || apiResult.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statut,
        message: messageApi442(corpsApi, 'API error'),
        status: 'API_ERROR'
      },
      _trace: { service_response: corpsApi, http_status: statut }
    }
  }];
}

// Succès. Les replis sur `inputData` restent, mais ce sont désormais de VRAIS
// replis : le corps de l'API est lu en premier, et il existe.
const responseBody = (corpsApi && typeof corpsApi === 'object') ? corpsApi : {};
return [{
  json: {
    success: true,
    message: 'Project registered successfully',
    project: {
      project_id: responseBody.project_id || inputData.project_id,
      display_name: responseBody.display_name || inputData.display_name,
      environment: responseBody.environment !== undefined ? responseBody.environment : null
    }
  }
}];

